// Writes the committed Shoelace 2.20.1 manifest subset (docs/api/shoelace-2.20.1.custom-elements.json) from a manifest
// generated by Shoelace's own analyzer configuration in a private scratch copy of the pinned source:
//   node scripts/api/shoelace-subset.mjs <generated custom-elements.json>
// Every Shoelace component is kept, so adding a Velcro component never edits this file; only the API fields the parity
// check and docs read are kept. The parity check compares the catalog's components only.
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { readCatalog } from '../site/catalog.mjs';
import { repoRoot, shoelaceManifestPath } from './model.mjs';

export const SHOELACE = {
  package: '@shoelace-style/shoelace',
  version: '2.20.1',
  tag: 'v2.20.1',
  commit: 'fb59fda70ed737c92611051b49bc7e3a5fed5dc5',
  license: 'MIT',
  copyright: 'Copyright (c) 2020 A Beautiful Site, LLC',
};

const keep = ['kind', 'name', 'tagName', 'summary', 'description', 'superclass', 'members', 'attributes', 'events', 'slots', 'cssParts', 'cssProperties'];
const memberKeep = ['kind', 'name', 'privacy', 'static', 'readonly', 'type', 'default', 'description', 'attribute', 'reflects', 'parameters', 'return', 'inheritedFrom'];
const pick = (obj, keys) => Object.fromEntries(keys.filter(k => obj[k] !== undefined).map(k => [k, obj[k]]));

export function subset(manifest, tags) {
  const modules = [];
  for (const mod of manifest.modules ?? []) {
    const declarations = (mod.declarations ?? []).filter(d => tags.has(d.tagName)).map(d => {
      const out = pick(d, keep);
      if (out.members) out.members = out.members.map(m => pick(m, memberKeep));
      if (out.events) out.events = out.events.map(e => pick(e, ['name', 'type', 'description']));
      return out;
    });
    if (declarations.length) modules.push({ kind: mod.kind, path: mod.path, declarations });
  }
  modules.sort((a, b) => a.path.localeCompare(b.path));
  return {
    schemaVersion: manifest.schemaVersion,
    'x-provenance': {
      ...SHOELACE,
      notice: `Subset of the Custom Elements Manifest that Shoelace ${SHOELACE.version}'s own analyzer configuration generates `
        + `from tag ${SHOELACE.tag} (commit ${SHOELACE.commit}), limited to its components' API fields. `
        + `${SHOELACE.copyright}, MIT License. See THIRD_PARTY_NOTICES.md.`,
    },
    modules,
  };
}

if (import.meta.main) {
  const source = process.argv[2];
  if (!source) {
    process.stderr.write('usage: node scripts/api/shoelace-subset.mjs <generated custom-elements.json>\n');
    process.exit(2);
  }
  const { readFileSync } = await import('node:fs');
  const manifest = JSON.parse(readFileSync(source, 'utf8'));
  const tags = new Set((manifest.modules ?? []).flatMap(m => (m.declarations ?? []).map(d => d.tagName)).filter(Boolean));
  const out = subset(manifest, tags);
  const found = out.modules.flatMap(m => m.declarations).length;
  const missing = readCatalog(repoRoot).filter(c => !tags.has(c.tag)).length;
  if (missing) {
    process.stderr.write(`shoelace-subset: ${missing} catalog component(s) missing from the source manifest\n`);
    process.exit(1);
  }
  writeFileSync(path.join(repoRoot, shoelaceManifestPath), `${JSON.stringify(out, null, 2)}\n`);
  process.stdout.write(`shoelace-subset: wrote ${found} components\n`);
}
